WITH parsed AS (SELECT id, effective_from, currency, tier_limits, tier_prices, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE currency <> 'USD') SELECT *, CUME_DIST() OVER (PARTITION BY currency ORDER BY avg_tier_price NULLS FIRST) AS avg_tier_price_cume_dist, PERCENT_RANK() OVER (PARTITION BY currency ORDER BY entry_price NULLS LAST) AS entry_price_percent_rank FROM parsed
